const CALC_QUESTIONS = [];
const CALC_UNIT_COUNTS = {};

function calcQuestion(unit, topicCode, topic, skill, calculatorAllowed, stem, correct, distractors, stimulusGroupId, stimulus) {
  const number = (CALC_UNIT_COUNTS[unit] || 0) + 1;
  CALC_UNIT_COUNTS[unit] = number;
  const correctIndex = CALC_QUESTIONS.length % 4;
  const options = distractors.slice();
  options.splice(correctIndex, 0, correct);
  CALC_QUESTIONS.push({
    id: `apcalc-${unit.toLowerCase()}-${String(number).padStart(3, "0")}`,
    unit,
    topicCode,
    topic,
    skill,
    calculatorAllowed,
    type: "s",
    stimulusGroupId: stimulusGroupId || null,
    ...(stimulus ? { stimulus } : {}),
    q: stem,
    o: options,
    c: [correctIndex],
    e: "",
  });
}

const q = calcQuestion;

// Unit 1 — Limits and Continuity
q("U1", "1.1", "Introducing Calculus: Can Change Occur at an Instant?", "2", false, "A student computes the average rate of change of a differentiable function s(t), which gives the position in meters of an object at time t in seconds, over the interval [2, 2+h] for smaller and smaller positive values of h. As h → 0, this process of shrinking the interval around t = 2 allows the student to define which quantity?", "The instantaneous rate of change of s at t = 2, defined as the limit of the average rates of change as h approaches 0.", ["The average rate of change of s over the interval [2,3], since h must eventually equal 1.", "The total distance traveled by the object from t = 0 to t = 2.", "The value of s(2), since shrinking the interval isolates a single output value."]);
q("U1", "1.2", "Defining Limits and Limit Notation", "4", false, "Suppose lim_{x→5^-} g(x) = 8 and lim_{x→5^+} g(x) = 8, but g(5) = 2. Which statement correctly uses limit notation to describe the behavior of g near x = 5?", "lim_{x→5} g(x) = 8, even though g(5) ≠ 8, because the two one-sided limits agree with each other.", ["lim_{x→5} g(x) = 2, because a two-sided limit must always equal the function value at that point.", "lim_{x→5} g(x) does not exist, because g(5) is not equal to 8.", "lim_{x→5} g(x) = 8 only if g happens to be defined at points near x = 5 other than x = 5 itself."]);
q("U1", "1.3", "Estimating Limit Values from Graphs", "2", false, "The graph of a function h consists of the curve y = √x for 0 ≤ x < 4, a closed dot at (4, 1), and the line y = x − 3 for x > 4. Based on this graph, what is lim_{x→4} h(x)?", "The limit does not exist, because the left-hand limit is 2 and the right-hand limit is 1.", ["1, because h(4) = 1.", "2, because √4 = 2.", "1.5, the average of the values approached from each side."]);
q("U1", "1.4", "Estimating Limit Values from Tables", "2", true, "The table shows values of f(x) = (x² − 4)/(x − 2) for x near 2 (note that f is undefined at x = 2). Based on the pattern in the table, what is the best estimate for lim_{x→2} f(x)?", "4", ["3.9, since that is the closest tabulated value to x = 2 from the left", "0, since f(2) is undefined", "Cannot be estimated without knowing f(2)"], "apcalc-g-u1-limit-table", CALC_STIMULI.u1LimitTable);
q("U1", "1.4", "Estimating Limit Values from Tables", "3", false, "Using the same table of values for f(x) = (x² − 4)/(x − 2) near x = 2, which statement best explains why the table only provides an estimate of lim_{x→2} f(x) rather than a proof of its exact value?", "A table can only ever show finitely many values of x, so it cannot confirm the trend continues for every x arbitrarily close to 2.", ["Tables can never be used reliably because calculators round decimal values.", "The table is inconclusive because f(2) is undefined, so no conclusion about the limit can be drawn.", "A proof requires evaluating f at x = 2 exactly, which the table does not do."], "apcalc-g-u1-limit-table", CALC_STIMULI.u1LimitTable);
q("U1", "1.5", "Determining Limits Using Algebraic Properties of Limits", "1", false, "Given that lim_{x→a} f(x) = 3 and lim_{x→a} g(x) = −2, use the algebraic limit laws to find lim_{x→a} [4f(x) − g(x)²].", "8", ["16", "14", "-4"]);
q("U1", "1.6", "Determining Limits Using Algebraic Manipulation", "1", false, "Evaluate lim_{x→3} (x² − 9)/(x − 3).", "6", ["0, since the denominator is 0 at x = 3", "The limit does not exist, since x − 3 = 0 is not in the domain", "3, the value that x approaches"]);
q("U1", "1.6", "Determining Limits Using Algebraic Manipulation", "1", false, "Evaluate lim_{x→0} (√(x+4) − 2)/x.", "1/4", ["0, by substituting x = 0 directly into the simplified radical", "4, the value under the radical when x = 0", "Does not exist, because the denominator approaches 0"]);
q("U1", "1.7", "Selecting Procedures for Determining Limits", "3", false, "Which procedure is most appropriate for evaluating lim_{x→1} (x³ − 1)/(x − 1)?", "Factor the numerator as a difference of cubes, (x−1)(x²+x+1), and cancel the common factor with the denominator before substituting.", ["Substitute x = 1 directly and report the resulting 0/0 as the final numerical answer.", "Multiply numerator and denominator by the conjugate of the numerator, since it contains a difference.", "Apply the squeeze theorem using x³ − 2 and x³ as bounding functions."]);
q("U1", "1.8", "Determining Limits Using the Squeeze Theorem", "3", true, "Since −x² ≤ x²sin(1/x) ≤ x² for all x ≠ 0, and a calculator shows the outputs of x²sin(1/x) oscillating but shrinking toward 0 as x approaches 0 (e.g., at x = 0.1, 0.01, 0.001), what does the Squeeze Theorem allow you to conclude about lim_{x→0} x² sin(1/x)?", "The limit equals 0, because both bounding functions −x² and x² approach 0 as x → 0.", ["The limit does not exist, because sin(1/x) oscillates infinitely often near x = 0.", "The limit equals 1, since sin(1/x) is bounded between −1 and 1.", "The limit cannot be determined without evaluating x² sin(1/x) at x = 0 directly."]);
q("U1", "1.9", "Connecting Multiple Representations of Limits", "2", false, "A table of values for f shows outputs approaching 5 as x approaches 3 from both sides. A separate graph of f shows an open circle at (3, 5) with no other point plotted directly above or below x = 3. Which conclusion is consistent with both representations?", "lim_{x→3} f(x) = 5, but f(3) is undefined.", ["f(3) = 5, since both representations show the value 5 at x = 3.", "lim_{x→3} f(x) does not exist, since the graph has an open circle there.", "f is continuous at x = 3, since the limit and the graph agree."]);
q("U1", "1.10", "Exploring Types of Discontinuities", "3", true, "Let f(x) = sin(x)/x for x ≠ 0, and f(0) = 3. A calculator table shows sin(x)/x approaching 1 as x approaches 0 from both directions. What type of discontinuity does f have at x = 0?", "A removable discontinuity, because lim_{x→0} f(x) = 1 exists but does not equal f(0) = 3.", ["A jump discontinuity, because the left- and right-hand limits are different.", "An infinite discontinuity, because f is undefined by a fraction at x = 0.", "No discontinuity, because f(0) is defined and the limit exists."]);
q("U1", "1.11", "Defining Continuity at a Point", "1", false, "Let f(x) = 3x + k for x ≤ 2, and f(x) = x² for x > 2. Find the value of k that makes f continuous at x = 2.", "-2", ["2, from setting 3(2)+k equal to 2(2)", "-6, from solving 3(2)+k = 0", "4, from setting k equal to the right-hand limit directly"]);
q("U1", "1.11", "Defining Continuity at a Point", "4", false, "Which set of conditions must all hold for a function f to be continuous at x = c, according to the formal definition of continuity at a point?", "f(c) is defined, lim_{x→c} f(x) exists, and lim_{x→c} f(x) = f(c).", ["f(c) is defined and f is differentiable at x = c.", "lim_{x→c} f(x) exists, regardless of whether f(c) is defined.", "f(c) is defined and the one-sided limits at c are both positive."]);
q("U1", "1.12", "Confirming Continuity over an Interval", "3", true, "Consider f(x) = √(4 − x²) on the closed interval [−2, 2]. Using a calculator to evaluate f at several points across the interval, including near the endpoints (e.g., x = −1.99, 0, 1.99), a student observes no jumps, breaks, or undefined outputs. Is f continuous on [−2, 2]?", "Yes, because 4 − x² ≥ 0 throughout [−2, 2], and √(4−x²) is a composition of functions continuous on that domain.", ["No, because f is undefined at x = −2 and x = 2, where the expression under the radical equals 0.", "No, because f is only continuous on the open interval (−2, 2), not at the endpoints.", "Cannot be determined without checking every real number in the interval individually."]);
q("U1", "1.13", "Removing Discontinuities", "1", false, "The function g(x) = (x² − x − 2)/(x − 2) has a removable discontinuity at x = 2. What value should be assigned to g(2) to make g continuous at x = 2?", "3", ["2, the x-value where the discontinuity occurs", "-1, the root of the simplified factor x + 1", "0, since the original expression is undefined at x = 2"]);
q("U1", "1.14", "Connecting Infinite Limits and Vertical Asymptotes", "2", true, "Let f(x) = (x+1)/(x−3)². A calculator table of values for x = 2.9, 2.99, 3.01, 3.1 shows f(x) growing very large and positive as x approaches 3 from both sides. What does this indicate about lim_{x→3} f(x) and the graph of f?", "lim_{x→3} f(x) = +∞, and the graph of f has a vertical asymptote at x = 3.", ["lim_{x→3} f(x) = −∞, since the denominator approaches 0 from the negative direction.", "lim_{x→3} f(x) = 0, since dividing by an increasingly large denominator makes outputs shrink.", "lim_{x→3} f(x) does not exist in any meaningful sense, so no conclusion can be drawn about the graph."]);
q("U1", "1.15", "Connecting Limits at Infinity and Horizontal Asymptotes", "1", true, "Evaluate lim_{x→∞} (3x² + 2x)/(5x² − 7).", "3/5", ["2/7, from comparing the coefficients of the linear and constant terms", "0, since the degrees of numerator and denominator are equal so the limit must vanish", "∞, since both the numerator and denominator grow without bound"]);
q("U1", "1.16", "Working with the Intermediate Value Theorem", "3", false, "Suppose f is continuous on [0, 3], with f(0) = −2 and f(3) = 5. Which conclusion is justified by the Intermediate Value Theorem?", "There exists at least one c in (0, 3) such that f(c) = 0.", ["There exists exactly one c in (0, 3) such that f(c) = 0.", "f must be increasing on (0, 3), since f(0) < f(3).", "No conclusion can be drawn unless f is also known to be differentiable on (0, 3)."]);
q("U1", "1.16", "Working with the Intermediate Value Theorem", "3", true, "Let f(x) = cos(x) − x on [0, 1]. A calculator gives f(0) = 1 and f(1) = cos(1) − 1 ≈ −0.460. Since f is continuous on [0, 1], what can be concluded by the Intermediate Value Theorem?", "There is at least one value c in (0, 1) where f(c) = 0, meaning cos(c) = c.", ["f(x) = 0 has no solution on [0, 1], since f(0) and f(1) are both nonzero.", "There is exactly one value c in (0, 1) where f(c) = 0, since IVT guarantees a unique root.", "f must be zero at the midpoint x = 0.5, since that is halfway between the endpoints."]);

// Unit 2 — Differentiation: Definition and Fundamental Properties
q("U2", "2.1", "Defining Average and Instantaneous Rates of Change at a Point", "2", true, "The table below gives the position s(t), in meters, of a particle moving along a straight line at selected times t, in seconds.\n\nt (s):      0     1.5     3     4.5\ns(t) (m):  2.3    9.8   15.1   22.4\n\nWhat is the average velocity of the particle, in meters per second, over the interval [1.5, 4.5]?", "4.2 m/s", ["4.47 m/s", "-4.2 m/s", "3.53 m/s"]);
q("U2", "2.2", "Defining the Derivative of a Function and Using Derivative Notation", "4", false, "Let f be a function that is differentiable at x = 3. Which of the following limit expressions is equal to f'(3) by the formal definition of the derivative?", "lim(h→0) [f(3+h) - f(3)] / h", ["lim(h→0) [f(3+h) - f(3)] / 3", "lim(h→0) [f(3) - f(3+h)] / h", "lim(h→0) [f(3+h) - f(3-h)] / h"]);
q("U2", "2.3", "Estimating Derivatives of a Function at a Point", "2", true, "The table shows values of a differentiable function g near x = 1.6.\n\nx:      1.4      1.5      1.6      1.7      1.8\ng(x):  3.912    4.055    4.200    4.347    4.496\n\nUsing the data in the table, what is the best estimate for g'(1.6)?", "1.46", ["1.47", "1.45", "0.292"]);
q("U2", "2.4", "Connecting Differentiability and Continuity — When Derivatives Do and Do Not Exist", "3", false, "Let f(x) = |x - 2| + 1. Which statement about f at x = 2 is true?", "f is continuous at x = 2 but not differentiable at x = 2, since the left-hand and right-hand derivatives at x = 2 are not equal.", ["f is differentiable at x = 2 because f is continuous there, and continuity always implies differentiability.", "f is neither continuous nor differentiable at x = 2, since f has a sharp corner there.", "f is differentiable at x = 2 with f'(2) = 0, since the graph has a minimum point there."]);
q("U2", "2.4", "Connecting Differentiability and Continuity — When Derivatives Do and Do Not Exist", "3", false, "The function h is defined by h(x) = x^(2/3) for all real numbers. Which statement correctly describes the behavior of h at x = 0?", "h is continuous at x = 0 but not differentiable at x = 0, because h'(x) = (2/3)x^(-1/3) increases without bound in magnitude as x approaches 0.", ["h is not continuous at x = 0 because x^(2/3) is undefined when x = 0.", "h is differentiable at x = 0 with h'(0) = 0, since x = 0 is a minimum point of the graph.", "h is differentiable everywhere, including at x = 0, because every power function of x is differentiable for all real numbers."]);
q("U2", "2.5", "Applying the Power Rule", "1", false, "If f(x) = 4x^5 - 3/x^2 + sqrt(x), what is f'(x)?", "20x^4 + 6/x^3 + 1/(2 sqrt(x))", ["20x^4 - 6/x^3 + 1/(2 sqrt(x))", "4x^4 + 6/x^3 + 1/(2 sqrt(x))", "20x^4 + 6/x^3 + (1/2) sqrt(x)"]);
q("U2", "2.6", "Derivative Rules: Constant, Sum, Difference, and Constant Multiple", "1", false, "Let f(x) = 7 and g(x) = 2x^3 - 5x + 9. If h(x) = 3g(x) - 4f(x), what is h'(x)?", "18x^2 - 15", ["18x^2 - 43", "18x^2 + 15", "6x^2 - 5"]);
q("U2", "2.7", "Derivatives of cos x, sin x, e^x, and ln x", "1", false, "What is the derivative of f(x) = 5cos(x) - 3e^x + 2ln(x)?", "-5sin(x) - 3e^x + 2/x", ["5sin(x) - 3e^x + 2/x", "-5sin(x) - 3x·e^(x-1) + 2/x", "-5sin(x) - 3e^x + 1/x"]);
q("U2", "2.8", "The Product Rule", "1", false, "If f(x) = x^3 · e^x, what is f'(x)?", "3x^2 e^x + x^3 e^x", ["3x^2 e^x", "x^3 e^x", "3x^2 + e^x"]);
q("U2", "2.8", "The Product Rule", "2", true, "The functions p and q are differentiable for all real numbers. The table gives values at x = 5.\n\np(5) = 3.6,  p'(5) = -1.2,  q(5) = 2.5,  q'(5) = 4.1\n\nIf r(x) = p(x)·q(x), what is r'(5)?", "11.76", ["-4.92", "-17.76", "9"]);
q("U2", "2.9", "The Quotient Rule", "1", false, "If f(x) = (2x^2 - 1)/(x + 3), what is f'(x)?", "(2x^2 + 12x + 1)/(x + 3)^2", ["(-2x^2 - 12x - 1)/(x + 3)^2", "(2x^2 + 12x + 1)/(x + 3)", "(6x^2 + 12x - 1)/(x + 3)^2"]);
q("U2", "2.9", "The Quotient Rule", "2", true, "The functions u and v are differentiable for all real numbers, with v(x) ≠ 0. The table gives values at x = -1.\n\nu(-1) = 6.4,  u'(-1) = -2.1,  v(-1) = 1.6,  v'(-1) = 3.3\n\nIf w(x) = u(x)/v(x), what is w'(-1)?", "-9.5625", ["9.5625", "-15.3", "6.9375"]);
q("U2", "2.10", "Derivatives of Tangent, Cotangent, Secant, and/or Cosecant", "1", false, "What is the derivative of f(x) = tan(x) - 3sec(x)?", "sec^2(x) - 3sec(x)tan(x)", ["sec(x)tan(x) - 3sec^2(x)", "sec^2(x) - 3tan(x)", "sec^2(x) + 3sec(x)tan(x)"]);
q("U2", "2.10", "Derivatives of Tangent, Cotangent, Secant, and/or Cosecant", "1", false, "What is the derivative of g(x) = 4cot(x) + csc(x)?", "-4csc^2(x) - csc(x)cot(x)", ["-4csc^2(x) + csc(x)cot(x)", "4csc^2(x) - csc(x)cot(x)", "-4csc(x)cot(x) - csc(x)cot(x)"]);

// Unit 3 — Differentiation: Composite, Implicit, and Inverse Functions
q("U3", "3.1", "The Chain Rule", "1", false, "Let h(x) = sin(3x^2 - 1). What is h'(x)?", "6x cos(3x^2 - 1)", ["cos(3x^2 - 1)", "3x^2 cos(3x^2 - 1)", "-6x cos(3x^2 - 1)"]);
q("U3", "3.1", "The Chain Rule", "1", false, "If g(x) = (5x^3 + 2x)^4, what is g'(x)?", "4(5x^3 + 2x)^3(15x^2 + 2)", ["(5x^3 + 2x)^3(15x^2 + 2)", "4(5x^3 + 2x)^4(15x^2 + 2)", "4(5x^3 + 2x)^3(15x^2)"]);
q("U3", "3.1", "The Chain Rule", "4", false, "If f and g are differentiable functions, which expression correctly gives d/dx[f(g(x))] using proper chain rule notation?", "f'(g(x)) · g'(x)", ["f'(x) · g'(x)", "f'(g(x))", "f'(g'(x)) · g'(x)"]);
q("U3", "3.2", "Implicit Differentiation", "1", false, "If x^2y + y^3 = 10 defines y implicitly as a function of x, what is dy/dx?", "-2xy / (x^2 + 3y^2)", ["-(2xy + 3y^2) / x^2", "2xy / (x^2 + 3y^2)", "-2xy / (3y^2)"]);
q("U3", "3.2", "Implicit Differentiation", "1", false, "If x^2 + xy + y^2 = 7 defines y implicitly as a function of x, what is dy/dx?", "-(2x + y) / (x + 2y)", ["-2x / (x + 2y)", "(2x + y) / (x + 2y)", "-(2x + 3y) / x"]);
q("U3", "3.2", "Implicit Differentiation", "1", false, "If sin(y) + xy = x^2 defines y implicitly as a function of x, what is dy/dx?", "(2x - y) / (cos y + x)", ["(2x - y) / cos y", "2x / (cos y + x)", "(2x - y) / (x - cos y)"]);
q("U3", "3.3", "Differentiating Inverse Functions", "3", false, "Let f be a differentiable, invertible function with f(1) = 4 and f'(1) = 5. If g = f^(-1), what is g'(4)?", "1/5", ["5", "1/4", "-1/5"]);
q("U3", "3.4", "Differentiating Inverse Trigonometric Functions", "1", true, "Let f(x) = arcsin(2x). What is f'(0.2), rounded to three decimal places?", "2.182", ["1.091", "-2.182", "2.085"]);
q("U3", "3.5", "Selecting Procedures for Calculating Derivatives", "1", true, "If y = e^(3x) sqrt(x^2 + 1), what is dy/dx at x = 2, rounded to one decimal place?", "3067.1", ["1082.5", "2796.5", "1262.9"]);
q("U3", "3.6", "Calculating Higher-Order Derivatives", "1", true, "For the curve defined by x^2 + y^2 = 25, what is the value of d^2y/dx^2 at the point (3, 4)?", "-25/64", ["-25/4", "25/64", "-9/64"]);

// Unit 4 — Contextual Applications of Differentiation
q("U4", "4.1", "Interpreting the Meaning of the Derivative in Context", "4", false, "The temperature of a cup of coffee, in degrees Fahrenheit, t minutes after it is poured, is given by a differentiable function H. What are the units of H'(t), and what does H'(6) = -3 mean in the context of the problem?", "Degrees Fahrenheit per minute; at t = 6 minutes, the coffee's temperature is decreasing at a rate of 3°F per minute.", ["Degrees Fahrenheit; at t = 6 minutes, the temperature of the coffee is 3 degrees below the temperature it had when it was poured.", "Minutes per degree Fahrenheit; at t = 6 minutes, the coffee's temperature takes 3 minutes to change by one degree Fahrenheit.", "Degrees Fahrenheit per minute; over the interval from t = 0 to t = 6 minutes, the coffee's temperature decreased at an average rate of 3 degrees Fahrenheit per minute."]);
q("U4", "4.2", "Straight-Line Motion: Connecting Position, Velocity, and Acceleration", "4", false, "The table above gives the velocity v(t), in meters per second, of a particle moving along a straight line at selected times t. Based on the table, what does the value v(4) = -2 mean in the context of the problem?", "At t = 4 seconds, the particle is moving in the negative direction at a speed of 2 meters per second.", ["At t = 4 seconds, the particle's position is 2 meters to the left of the origin.", "Between t = 0 and t = 4 seconds, the particle's average velocity was -2 meters per second.", "At t = 4 seconds, the particle's acceleration is -2 meters per second per second."], "apcalc-g-u4-velocity-table", CALC_STIMULI.u4VelocityTable);
q("U4", "4.2", "Straight-Line Motion: Connecting Position, Velocity, and Acceleration", "2", true, "Using the data in the table above, what is the approximate acceleration of the particle, in m/s², at t = 4 seconds, found using the average rate of change of velocity over the interval 2 ≤ t ≤ 6?", "-4.5 m/s²", ["-2.25 m/s²", "-4 m/s²", "-5 m/s²"], "apcalc-g-u4-velocity-table", CALC_STIMULI.u4VelocityTable);
q("U4", "4.2", "Straight-Line Motion: Connecting Position, Velocity, and Acceleration", "1", false, "A particle moves along the x-axis so that its position at time t ≥ 0 seconds is given by x(t) = t^3 - 6t^2 + 9t, where x(t) is measured in meters. For which values of t is the particle moving in the negative direction?", "1 < t < 3", ["0 ≤ t < 1 or t > 3", "t < 1 or t > 3", "t = 1 and t = 3 only"]);
q("U4", "4.2", "Straight-Line Motion: Connecting Position, Velocity, and Acceleration", "1", false, "A particle moves along the x-axis so that its position at time t ≥ 0 seconds is given by x(t) = t^3 - 9t^2 + 24t, where x(t) is measured in meters. For which values of t is the particle moving in the negative direction?", "2 < t < 4", ["0 ≤ t < 2 or t > 4", "t < 2 or t > 4", "t = 2 and t = 4 only"]);
q("U4", "4.3", "Rates of Change in Applied Contexts Other than Motion", "4", false, "Air is being pumped into a spherical balloon. The volume V of the balloon, in cubic centimeters, is a differentiable function of time t, in seconds. What does the statement dV/dt = 15 when t = 3 mean in the context of the problem?", "At t = 3 seconds, the balloon's volume is increasing at an instantaneous rate of 15 cm³/sec.", ["At t = 3 seconds, the volume of the balloon is 15 cubic centimeters.", "Between t = 0 and t = 3 seconds, the volume of the balloon increased by a total of 15 cubic centimeters, regardless of the rate at any particular instant.", "At t = 3 seconds, it takes 15 seconds for the volume to increase by one cubic centimeter."]);
q("U4", "4.4", "Introduction to Related Rates", "2", false, "A spherical snowball melts so that its volume V decreases over time t. The volume of a sphere of radius r is V = (4/3)πr^3. Which equation results from differentiating both sides of this equation with respect to t?", "dV/dt = 4πr^2 (dr/dt)", ["dV/dt = 4πr^2", "dV/dt = (4/3)πr^2 (dr/dt)", "dV/dt = 4π(3r^2)(dr/dt)^2"]);
q("U4", "4.5", "Solving Related Rates Problems", "1", true, "A 13-foot ladder leans against a vertical wall, with the bottom of the ladder on level ground. The bottom of the ladder slides away from the wall at a constant rate of 2 feet per second. At the instant when the bottom of the ladder is 5 feet from the wall, how fast is the top of the ladder sliding down the wall?", "5/6 ft/sec", ["5/12 ft/sec", "24/5 ft/sec", "2 ft/sec"]);
q("U4", "4.5", "Solving Related Rates Problems", "1", true, "A 10-foot ladder leans against a vertical wall, with the bottom of the ladder on level ground. The bottom of the ladder slides away from the wall at a constant rate of 2 feet per second. At the instant when the bottom of the ladder is 6 feet from the wall, how fast is the top of the ladder sliding down the wall?", "3/2 ft/sec", ["3/4 ft/sec", "8/3 ft/sec", "2 ft/sec"]);
q("U4", "4.5", "Solving Related Rates Problems", "1", true, "Oil spilled from a tanker spreads outward in the shape of a circle on the surface of the water. The radius of the circular oil slick is increasing at a constant rate of 3 meters per minute. At the instant when the radius is 50 meters, how fast is the area of the oil slick increasing?", "300π m²/min", ["150π m²/min", "6π m²/min", "300 m²/min"]);
q("U4", "4.6", "Approximating Values of a Function Using Local Linearity and Linearization", "1", true, "Let f(x) = √x. The tangent line to the graph of f at x = 25 is used to approximate values of f near x = 25. Using this linear approximation, estimate the value of √26.5.", "5.15", ["5.1", "5.3", "5.03"]);
q("U4", "4.7", "Using L'Hopital's Rule for Determining Limits in Indeterminate Forms", "1", false, "What is the value of lim (x→0) (1 - cos(2x)) / x^2 ?", "2", ["0", "1", "-2"]);

// Unit 5 — Analytical Applications of Differentiation
q("U5", "5.1", "Using the Mean Value Theorem", "1", false, "Let f(x) = x^2 on the closed interval [1, 5]. Since f is a polynomial, it is continuous on [1, 5] and differentiable on (1, 5), so the Mean Value Theorem applies. What value of c in (1, 5) satisfies f'(c) = [f(5) - f(1)] / (5 - 1)?", "c = 3", ["c = 6", "c = 2", "c = 4"]);
q("U5", "5.1", "Using the Mean Value Theorem", "1", true, "Let f(x) = x^3 - 2x on the closed interval [0, 2]. f is continuous on [0,2] and differentiable on (0,2), so the Mean Value Theorem guarantees at least one c in (0,2) with f'(c) equal to the average rate of change of f on [0,2]. Find this value of c, rounded to three decimal places.", "c ≈ 1.155", ["c ≈ -1.155", "c ≈ 1.333", "c = 2"]);
q("U5", "5.2", "Extreme Value Theorem, Global vs Local Extrema, and Critical Points", "3", false, "Let f(x) = 1/(x-2) on the closed interval [0, 4]. Which statement correctly evaluates whether the Extreme Value Theorem guarantees that f has an absolute maximum and an absolute minimum on [0, 4]?", "The EVT does not apply, because f is not continuous on [0,4]; f is undefined at x=2, which is in the interval.", ["The EVT guarantees an absolute max and min, because f(0) and f(4) are both defined.", "The EVT does not apply, because f is not differentiable at the endpoints x=0 and x=4.", "The EVT guarantees an absolute max and min, because every rational function is continuous on its domain."]);
q("U5", "5.2", "Extreme Value Theorem, Global vs Local Extrema, and Critical Points", "1", false, "Let f(x) = (x-1)^(2/3), defined for all real numbers. What are the critical number(s) of f?", "x = 1 only", ["There are no critical numbers, since f'(x) is never equal to 0.", "x = 0, since f(0) is where the function's base value equals 1.", "x = 1 and x = -1, by symmetry of the exponent."]);
q("U5", "5.3", "Determining Intervals on Which a Function Is Increasing or Decreasing", "2", false, "The figure shows the graph of f'(x), the derivative of f, on the interval [-4, 6]. Based on the graph, on which of the following intervals is f increasing?", "(2, 4)", ["(-1, 2)", "(4, 6)", "(-4, 6)"], "apcalc-g-u5-derivative-graph", CALC_STIMULI.u5DerivativeGraph);
q("U5", "5.4", "Using the First Derivative Test to Determine Relative (Local) Extrema", "2", false, "Using the same graph of f'(x) on [-4, 6], at which x-value does f have a local maximum?", "x = -1", ["x = 2", "x = -4", "x = 6"], "apcalc-g-u5-derivative-graph", CALC_STIMULI.u5DerivativeGraph);
q("U5", "5.4", "Using the First Derivative Test to Determine Relative (Local) Extrema", "1", false, "Let f(x) = 2x^3 - 3x^2 - 12x + 5. Use the First Derivative Test to determine the behavior of f at its critical number x = -1.", "f has a local maximum at x = -1, since f'(x) changes from positive to negative there.", ["f has a local minimum at x = -1, since f'(x) changes from negative to positive there.", "f has neither a local max nor min at x = -1, since f''(-1) = 0 as well.", "f has a local maximum at x = -1, since f(-1) is greater than f(2)."]);
q("U5", "5.5", "Using the Candidates Test to Determine Absolute (Global) Extrema", "3", true, "Let p(x) = x^3 - 4x^2 + 2 on the closed interval [-1, 3]. Using the Candidates Test, what is the absolute minimum value of p on this interval?", "-202/27 ≈ -7.481, attained at x = 8/3", ["-7, attained at the endpoint x = 3", "-3, attained at the endpoint x = -1", "2, attained at the critical point x = 0"]);
q("U5", "5.5", "Using the Candidates Test to Determine Absolute (Global) Extrema", "3", true, "Let p(x) = x^3 - 6x on the closed interval [-3, 1]. Using the Candidates Test, what is the absolute maximum value of p on this interval?", "4√2 ≈ 5.657, attained at x = -√2", ["-9, attained at the endpoint x = -3", "-5, attained at the endpoint x = 1", "-4√2 ≈ -5.657, attained at x = -√2"]);
q("U5", "5.6", "Determining Concavity", "2", false, "The table gives values of a twice-differentiable function f and its derivatives f' and f'' at selected x-values on [-2, 6]. Assume f' and f'' do not change sign between consecutive listed x-values except where the table indicates a sign change. On which interval is the graph of f concave down?", "(-2, 2)", ["(2, 6)", "(-2, 6)", "(0, 4)"], "apcalc-g-u5-sign-table", CALC_STIMULI.u5SignTable);
q("U5", "5.7", "Using the Second Derivative Test to Determine Extrema", "4", false, "Let f(x) = x^3 - 3x^2 - 9x + 1. Which of the following is a correctly notated justification, using the Second Derivative Test, that f has a local maximum at x = -1?", "Since f'(-1) = 0 and f''(-1) = -12 < 0, f has a local maximum at x = -1.", ["Since f''(-1) = 0 and f'(-1) = -12 < 0, f has a local maximum at x = -1.", "Since f'(-1) = -12 < 0, f has a local maximum at x = -1.", "Since f'(-1) = 0 and f''(-1) = -12 < 0, f has a local minimum at x = -1."]);
q("U5", "5.7", "Using the Second Derivative Test to Determine Extrema", "3", false, "Let h(x) = x^4. The Second Derivative Test is applied at the critical number x=0. Which statement correctly describes the outcome?", "The test is inconclusive because h''(0) = 0; applying the First Derivative Test instead shows h' changes from negative to positive at x=0, so x=0 is a local minimum.", ["The test shows x=0 is a local maximum, since h''(0)=0 indicates the graph is concave down there.", "The test shows x=0 is neither a local max nor min, since h''(0)=0 always rules out an extremum.", "The test shows x=0 is a local minimum, since h''(0)=0 confirms the graph is concave up there."]);
q("U5", "5.8", "Sketching Graphs of Functions and Their Derivatives", "2", false, "Suppose f is twice differentiable for all real x, with f'(x) > 0 for every x and f''(x) < 0 for every x. Which of the following best describes the graph of f?", "The graph is increasing everywhere, rising less and less steeply as x increases (always concave down).", ["The graph is decreasing everywhere, falling less and less steeply as x increases (concave up throughout).", "The graph is increasing everywhere, rising more and more steeply as x increases (concave up throughout).", "The graph increases, reaches a local maximum, and then decreases."]);
q("U5", "5.9", "Connecting a Function, Its First Derivative, and Its Second Derivative", "3", false, "Using the same table of values for f, f', and f'' on [-2, 6], which statement about f must be true?", "f has a point of inflection at x = 2, since f''(x) changes sign from negative to positive there.", ["f has a local maximum at x = 2, since f'(2) = 0.", "f has a local minimum at x = 2, since f''(2) = 0.", "f is decreasing on (-2, 0), since f''(x) < 0 on that interval."], "apcalc-g-u5-sign-table", CALC_STIMULI.u5SignTable);
q("U5", "5.12", "Exploring Behaviors of Implicit Relations", "1", false, "A curve is defined implicitly by x^2 + y^2 - 4x - 6y + 4 = 0. At which x-value(s) does the curve have a horizontal tangent line?", "x = 2 (at the points (2, 0) and (2, 6))", ["x = -1 and x = 5 (these are the x-values where the tangent lines are actually vertical)", "x = 3 (this is the x-coordinate of the curve's center, not a tangent condition)", "x = 0 (this is a y-coordinate of one point on the curve, not the correct x-value)"]);
q("U5", "5.10", "Introduction to Optimization Problems", "1", false, "A rectangular garden will be built against the side of a house, so fencing is needed on only the three sides that do not border the house. A total of 120 feet of fencing is available. Let x be the length (in feet) of the side of the garden parallel to the house. Which function gives the area A(x) of the garden, for 0 < x < 120?", "A(x) = 60x - x²/2", ["A(x) = 120x - x²", "A(x) = x(60 - x)", "A(x) = 30x - x²/4"]);
q("U5", "5.11", "Solving Optimization Problems", "1", true, "A cylindrical can with a top and bottom must hold a volume of 500 cubic centimeters. Find the radius r (in cm, to two decimal places) that minimizes the amount of material used to make the can (i.e., minimizes the total surface area), and confirm this radius gives a minimum.", "r ≈ 4.30 cm", ["r ≈ 5.42 cm", "r ≈ 8.92 cm", "r ≈ 79.58 cm"]);
q("U5", "5.11", "Solving Optimization Problems", "1", true, "An open-top box with a square base must have a volume of 50,000 cubic centimeters. Find the side length x (in cm, to two decimal places) of the base that minimizes the total surface area of the box (base plus four sides), and confirm this value gives a minimum.", "x ≈ 46.42 cm", ["x ≈ 29.24 cm", "x ≈ 92.83 cm", "x = 100,000 cm"]);

// Unit 6 — Integration and Accumulation of Change
q("U6", "6.1", "Integration and Accumulation of Change", "4", false, "Water is pumped out of a storage tank at a rate of r(t) = 4 - 0.2t gallons per minute, where t is measured in minutes for 0 ≤ t ≤ 15. Which of the following expressions gives the total number of gallons pumped out of the tank during the first 10 minutes?", "∫_{0}^{10} r(t) dt", ["r(10) - r(0)", "∫_{0}^{10} r'(t) dt", "(1/10) ∫_{0}^{10} r(t) dt"]);
q("U6", "6.2", "Integration and Accumulation of Change", "1", true, "The table gives selected values of the velocity v(t), in meters per second, of a particle moving along a straight line, recorded at 3-second intervals. Use a left Riemann sum with the four subintervals indicated by the table to estimate the total distance, in meters, traveled by the particle from t = 0 to t = 12 seconds.", "69 m", ["75 m", "72 m", "81 m"], "apcalc-g-u6-velocity-table", CALC_STIMULI.u6VelocityTable);
q("U6", "6.2", "Integration and Accumulation of Change", "1", true, "Oil leaks from a damaged tanker at a rate L(t), measured in liters per hour, where t is measured in hours. Selected values are given: L(0) = 50, L(2) = 42, L(4) = 35, L(6) = 25, L(8) = 15. Using a right Riemann sum with the four subintervals indicated by the data, estimate the total amount of oil, in liters, that leaked during the first 8 hours.", "234 liters", ["304 liters", "269 liters", "117 liters"]);
q("U6", "6.2", "Integration and Accumulation of Change", "1", true, "The rate at which rain falls during a storm is given by R(t), in inches per hour, with selected values R(0) = 0.2, R(1) = 0.5, R(2) = 0.9, R(3) = 0.6, R(4) = 0.3. Use a trapezoidal sum with the four subintervals indicated to estimate the total rainfall, in inches, during the 4-hour storm.", "2.25 in", ["2.2 in", "2.3 in", "4.5 in"]);
q("U6", "6.3", "Integration and Accumulation of Change", "4", false, "Using the velocity data in the table (measured at 3-second intervals from t = 0 to t = 12), which expression correctly represents a right Riemann sum with n = 4 subintervals for the total distance traveled, in meters, over [0, 12]?", "3[v(3) + v(6) + v(9) + v(12)]", ["3[v(0) + v(3) + v(6) + v(9)]", "v(3) + v(6) + v(9) + v(12)", "3[v(0) + v(3) + v(6) + v(9) + v(12)]"], "apcalc-g-u6-velocity-table", CALC_STIMULI.u6VelocityTable);
q("U6", "6.3", "Integration and Accumulation of Change", "4", false, "The definite integral ∫_{2}^{7} f(x) dx is defined as a limit of Riemann sums, where Δx = (7-2)/n and x_i is a sample point in the i-th subinterval. Which expression below correctly represents this limit?", "lim(n→∞) Σ_{i=1}^{n} f(x_i) Δx", ["Σ_{i=1}^{n} f(x_i) Δx", "lim(n→∞) Σ_{i=1}^{n} f(x_i)/n", "lim(n→∞) Σ_{i=1}^{n} f(x_i) (Δx)^2"]);
q("U6", "6.4", "Integration and Accumulation of Change", "1", false, "Let g(x) = ∫_{1}^{x^2} √(t^2 + 1) dt. Find g'(x).", "g'(x) = 2x√(x^4 + 1)", ["g'(x) = √(x^4 + 1)", "g'(x) = 2x√(x^2 + 1)", "g'(x) = √(x^2 + 1)"]);
q("U6", "6.4", "Integration and Accumulation of Change", "3", false, "Let f be a continuous function such that f(x) > 0 for x < 4, f(4) = 0, and f(x) < 0 for x > 4. If g(x) = ∫_{0}^{x} f(t) dt, which of the following correctly justifies that g has a local maximum at x = 4?", "g'(x) = f(x) changes from positive to negative at x = 4, so by the First Derivative Test, g has a local maximum at x = 4.", ["Since f(4) = 0, it follows that g(4) = 0, so g has a local maximum at x = 4.", "g'(x) = f(x) changes from negative to positive at x = 4, so g has a local maximum at x = 4.", "Since f is decreasing through x = 4, g is concave down for all x, so g has a local maximum at x = 4."]);
q("U6", "6.5", "Integration and Accumulation of Change", "2", false, "Let D(t) represent the total distance traveled by the particle described in the table, so that D(t) = ∫_{0}^{t} v(x) dx. Based on the table, on which interval is D increasing at a decreasing rate (that is, the particle is slowing down while still moving forward)?", "6 < t < 12", ["0 < t < 6", "0 < t < 12", "There is no such interval, because D is increasing for the entire table."], "apcalc-g-u6-velocity-table", CALC_STIMULI.u6VelocityTable);
q("U6", "6.6", "Integration and Accumulation of Change", "1", false, "Suppose ∫_{1}^{5} f(x) dx = 8, ∫_{3}^{5} f(x) dx = 5, and ∫_{1}^{3} g(x) dx = 4. Find ∫_{1}^{3} [2f(x) - g(x)] dx.", "2", ["22", "10", "-1"]);
q("U6", "6.7", "Integration and Accumulation of Change", "1", false, "Evaluate ∫_{1}^{4} (3√x - 2/x^2) dx.", "25/2", ["-25/2", "31/2", "19/6"]);
q("U6", "6.7", "Integration and Accumulation of Change", "1", true, "Evaluate ∫_{0}^{1} √(1 + x^3) dx. Which of the following is closest to the value of this integral?", "1.111", ["1.000", "1.500", "0.833"]);
q("U6", "6.8", "Integration and Accumulation of Change", "1", false, "If f'(x) = 6x^2 - 4x + 1 and f(1) = 5, find f(x).", "f(x) = 2x^3 - 2x^2 + x + 4", ["f(x) = 2x^3 - 2x^2 + x", "f(x) = 2x^3 - 4x^2 + x + 6", "f(x) = 2x^3 + 2x^2 + x"]);
q("U6", "6.8", "Integration and Accumulation of Change", "1", false, "If f'(x) = 4x^3 + 6x - 2 and f(0) = -1, find f(x).", "f(x) = x^4 + 3x^2 - 2x - 1", ["f(x) = x^4 + 3x^2 - 2x", "f(x) = x^4 + 6x^2 - 2x - 1", "f(x) = x^4 + 3x^2 + 2x - 1"]);
q("U6", "6.9", "Integration and Accumulation of Change", "1", false, "Find ∫ x cos(x^2) dx.", "(1/2) sin(x^2) + C", ["sin(x^2) + C", "-(1/2) sin(x^2) + C", "(1/2) sin(x) + C"]);
q("U6", "6.9", "Integration and Accumulation of Change", "1", false, "Find ∫ x^3 √(x^4 + 5) dx.", "(1/6)(x^4 + 5)^(3/2) + C", ["(1/4)(x^4 + 5)^(3/2) + C", "(2/3)(x^4 + 5)^(3/2) + C", "(1/6)(x^4 + 5)^(1/2) + C"]);
q("U6", "6.10", "Integration and Accumulation of Change", "1", false, "Find ∫ (2x^2 - x - 1)/(x + 1) dx.", "x^2 - 3x + 2 ln|x+1| + C", ["x^2 - 3x + C", "x^2 - 3x + ln|x+1| + C", "x^2 + 3x + 2 ln|x+1| + C"]);
q("U6", "6.14", "Integration and Accumulation of Change", "1", true, "Which technique of antidifferentiation should be used to evaluate ∫_{0}^{2} e^(-x^2) dx, and what is the resulting value?", "No elementary antiderivative exists for e^(-x^2), so a calculator's numerical integration must be used; the value is approximately 0.882.", ["Substitute u = -x^2, so du = -2x dx; the value is approximately 0.441.", "Apply the power rule directly to e^(-x^2), treating it like x^(-2); the value is approximately 1.772.", "Complete the square in the exponent and integrate as a basic exponential; the value is approximately 1.000."]);

// Unit 7 — Differential Equations
q("U7", "7.1", "Modeling Situations with Differential Equations", "2", false, "A cylindrical tank is draining: water leaks out through a small hole in the bottom so that the rate at which the volume V of water in the tank decreases is proportional to the square root of V. Which differential equation models this situation, where k is a positive constant?", "dV/dt = -k√V", ["dV/dt = k√V", "dV/dt = -kV²", "dV/dt = -k/√V"]);
q("U7", "7.2", "Verifying Solutions for Differential Equations", "1", false, "Which of the following functions is a solution to the differential equation dy/dx = 2xy?", "y = 5e^(x²)", ["y = 5e^(2x)", "y = x² + 5", "y = 5x²"]);
q("U7", "7.3", "Sketching Slope Fields", "2", false, "The slope field shown displays short line segments indicating the value of dy/dx at each plotted point (x, y). Which differential equation could have generated this slope field?", "dy/dx = xy/2", ["dy/dx = -xy/2", "dy/dx = x/y", "dy/dx = x + y"], "apcalc-g-u7-slope-field", CALC_STIMULI.u7SlopeField);
q("U7", "7.4", "Reasoning Using Slope Fields", "3", false, "Using the slope field shown for dy/dx = xy/2, suppose a particular solution curve passes through the point (2, 1). As x increases from x = 2, staying in the first quadrant, the curve is…", "increasing, and increasing at an increasing rate (concave up)", ["increasing, but at a decreasing rate (concave down)", "decreasing toward y = 0", "constant, since the slope field looks the same near every point on the curve"], "apcalc-g-u7-slope-field", CALC_STIMULI.u7SlopeField);
q("U7", "7.6", "Finding General Solutions Using Separation of Variables", "1", false, "Find the general solution to the differential equation dy/dx = x²/y.", "y² = (2/3)x³ + C", ["y² = (1/3)x³ + C", "y² = (2/3)x³ + Cx", "y = (2/3)x³ + C"]);
q("U7", "7.6", "Finding General Solutions Using Separation of Variables", "1", false, "Find the general solution to the differential equation dy/dx = x/y².", "y³ = (3/2)x² + C", ["y³ = (3/2)x² + Cx", "y³ = (2/3)x² + C", "y = (3/2)x² + C"]);
q("U7", "7.7", "Finding Particular Solutions Using Initial Conditions and Separation of Variables", "1", false, "Find the particular solution to dy/dx = 3x²y that satisfies y(0) = 2.", "y = 2e^(x³)", ["y = 2e^(x³/3)", "y = 2e^(3x)", "y = e^(x³) + 1"]);
q("U7", "7.7", "Finding Particular Solutions Using Initial Conditions and Separation of Variables", "1", true, "The function y = 5e^(x⁴) is the particular solution to dy/dx = 4x³y satisfying y(0) = 5. What is the value of y at x = 1.2, rounded to the nearest whole number?", "40", ["28", "8", "13"]);
q("U7", "7.8", "Exponential Models with Differential Equations", "1", true, "A town's population grows at a rate proportional to its size (dP/dt = kP). The population was 10,000 in 2020 and 13,000 in 2025. Assuming this continuous exponential growth continues, during which year will the population first exceed 20,000?", "2033", ["2036", "2031", "2022"]);
q("U7", "7.8", "Exponential Models with Differential Equations", "1", true, "A sample of a radioactive isotope decays according to dA/dt = -kA. If the sample decays to 25% of its original amount after 12 years, what is the value of k, rounded to three decimal places?", "k ≈ 0.116", ["k ≈ 0.058", "k ≈ 0.231", "k ≈ 1.386"]);

// Unit 8 — Applications of Integration
q("U8", "8.1", "Finding the Average Value of a Function on an Interval", "2", true, "The table gives the cross-sectional area A(x), in square centimeters, of a solid at several values of x, in centimeters, measured from one end of the solid. Using a trapezoidal approximation with the given data, what is the best estimate of the average cross-sectional area of the solid on the interval 0 ≤ x ≤ 8?", "17.5 cm²", ["16.5 cm²", "18.5 cm²", "16.8 cm²"], "apcalc-g-u8-cross-section-table", CALC_STIMULI.u8CrossSectionTable);
q("U8", "8.2", "Connecting Position, Velocity, and Acceleration of Functions Using Integrals", "1", false, "A particle moves along the x-axis with velocity v(t) = 3t² − 12t + 9 (meters per second) for 0 ≤ t ≤ 4. At time t = 0, the particle's position is x(0) = 2. What is the particle's position at t = 4?", "6", ["4", "−2", "14"]);
q("U8", "8.2", "Connecting Position, Velocity, and Acceleration of Functions Using Integrals", "3", true, "A particle moves along a line with velocity v(t) = 5 sin(t) − 2 (feet per second) for 0 ≤ t ≤ 3, where t is measured in radians. What is the total distance traveled by the particle over this time interval?", "5.106 feet", ["3.950 feet", "4.761 feet", "5.607 feet"]);
q("U8", "8.3", "Using Accumulation Functions and Definite Integrals in Applied Contexts", "1", true, "A storage tank contains 50 gallons of water at time t = 0. Water then flows into the tank at a rate of R(t) = 20 + 5 sin(t/2) gallons per minute, for 0 ≤ t ≤ 10 minutes. How many gallons of water are in the tank at time t = 10?", "257.163 gallons", ["207.163 gallons", "202.054 gallons", "252.180 gallons"]);
q("U8", "8.4", "Finding the Area Between Curves Expressed as Functions of x", "2", false, "The figure shows the region R enclosed by the graphs of f(x) = x + 2 and g(x) = x², which intersect at the two points shown. What is the area of R?", "9/2", ["15/2", "10/3", "3/2"], "apcalc-g-u8-region-graph", CALC_STIMULI.u8RegionGraph);
q("U8", "8.4", "Finding the Area Between Curves Expressed as Functions of x", "1", false, "Let R be the region enclosed by the curves f(x) = 8 − x² and g(x) = x². What is the area of R?", "64/3", ["80/3", "32/3", "128/3"]);
q("U8", "8.5", "Finding the Area Between Curves Expressed as Functions of y", "1", false, "Let R be the region enclosed by the curves x = 6 − y² and x = y, described as functions of y. What is the area of R?", "125/6", ["22/3", "55/3", "18"]);
q("U8", "8.6", "Finding the Area Between Curves That Intersect at More Than Two Points", "3", false, "The curve f(x) = x³ − 4x intersects the x-axis at x = −2, 0, and 2. What is the total area of the region(s) enclosed between the graph of f and the x-axis on the interval [−2, 2]?", "8", ["0", "4", "16"]);
q("U8", "8.7", "Volumes with Cross Sections: Squares and Rectangles", "2", true, "Using the table of cross-sectional areas A(x) and a right Riemann sum with the given subintervals, what is the estimate for the volume of the solid on the interval 0 ≤ x ≤ 8?", "148 cm³", ["132 cm³", "140 cm³", "74 cm³"], "apcalc-g-u8-cross-section-table", CALC_STIMULI.u8CrossSectionTable);
q("U8", "8.8", "Volumes with Cross Sections: Triangles and Semicircles", "1", false, "The base of a solid is the region between the curve y = √x and the x-axis on the interval 0 ≤ x ≤ 4. Cross sections of the solid perpendicular to the x-axis are semicircles whose diameter stretches from the x-axis to the curve. What is the volume of the solid?", "π", ["2π", "4π", "8"]);
q("U8", "8.9", "Volume with Disc Method: Revolving Around the x- or y-Axis", "1", false, "The region under the curve y = x² on the interval 0 ≤ x ≤ 2 is revolved about the x-axis. What is the volume of the resulting solid?", "32π/5", ["8π/3", "4π", "16π/5"]);
q("U8", "8.9", "Volume with Disc Method: Revolving Around the x- or y-Axis", "1", false, "The region between the curve x = y² and the y-axis on the interval 0 ≤ y ≤ 3 is revolved about the y-axis. What is the volume of the resulting solid?", "243π/5", ["9π", "32π/5", "243/5"]);
q("U8", "8.10", "Volume with Disc Method: Revolving Around Other Axes", "1", true, "Let R be the region bounded by y = e^(x/2) + 1 and y = 1 on the interval 0 ≤ x ≤ 2. R is revolved about the line y = 1. What is the volume of the resulting solid?", "π(e²−1) ≈ 20.072", ["2π(e−1) ≈ 10.796", "π(e²+4e−3) ≈ 47.948", "π(e−1) ≈ 5.398"]);
q("U8", "8.11", "Volume with Washer Method: Revolving Around the x- or y-Axis", "2", false, "The region R shown in the figure, bounded above by f(x) = x + 2 and below by g(x) = x², is revolved about the x-axis. What is the volume of the resulting solid?", "72π/5", ["21π", "18π", "9π/2"], "apcalc-g-u8-region-graph", CALC_STIMULI.u8RegionGraph);
q("U8", "8.11", "Volume with Washer Method: Revolving Around the x- or y-Axis", "1", true, "Let R be the region enclosed by f(x) = 8 − x² and g(x) = x + 3. R is revolved about the x-axis. What is the volume of the resulting solid?", "463.570", ["578.743", "50.388", "147.559"]);
q("U8", "8.12", "Volume with Washer Method: Revolving Around Other Axes", "4", false, "Let R be the region bounded by y = x² and y = 4. Which integral expression gives the volume of the solid formed when R is revolved about the line y = 6?", "π∫₋₂² [(6−x²)² − 2²] dx", ["π∫₋₂² (6−x²)² dx", "π∫₋₂² [(6−x²) − 2]² dx", "2π∫₋₂² (6−x²−2) dx"]);
q("U8", "8.13", "The Arc Length of a Smooth, Planar Curve and Distance Traveled", "1", false, "What is the length of the curve y = (2/3)x^(3/2) from x = 0 to x = 3?", "14/3", ["2√3", "12√3/5", "7"]);
q("U8", "8.13", "The Arc Length of a Smooth, Planar Curve and Distance Traveled", "1", true, "A particle moves along the curve y = sin(x) from x = 0 to x = π/2. What is the distance traveled by the particle along the curve (its arc length), rounded to three decimal places?", "1.910", ["1.000", "1.571", "1.862"]);

const CALC_EXPLANATIONS = {
  "apcalc-u1-001": "Instantaneous rate of change at a point is formally defined as the limit of average rates of change (difference quotients) over intervals that shrink to that point; this is the foundational idea connecting average and instantaneous change in calculus, not merely evaluating s(2) or fixing h at a particular value.",
  "apcalc-u1-002": "A two-sided limit exists and equals the common value of the one-sided limits regardless of whether the function is defined there or what value it takes; the limit describes the trend of g(x) as x approaches 5, not the function's actual output at 5.",
  "apcalc-u1-003": "As x→4⁻ along y=√x, h(x)→√4=2, while as x→4⁺ along y=x−3, h(x)→4−3=1; since the one-sided limits disagree, the two-sided limit fails to exist even though h(4) is separately defined as 1.",
  "apcalc-u1-004": "As x approaches 2 from both sides, the tabulated outputs cluster increasingly close to 4 (3.9, 3.99 from the left and 4.01, 4.1 from the right), which is the numerical signature of a limit; the fact that f(2) itself is undefined does not prevent the limit from existing, since limits describe behavior near a point, not at it.",
  "apcalc-u1-005": "Numerical tables sample only finitely many, specific input values, so while they can strongly suggest a limit's value, only algebraic techniques (like factoring and simplifying) can rigorously confirm the limit holds for all x sufficiently close to 2; the limit's existence is independent of whether f(2) itself is defined.",
  "apcalc-u1-006": "By the difference and constant multiple limit laws, lim[4f−g²] = 4·lim f − (lim g)² = 4(3) − (−2)² = 12 − 4 = 8; common errors include adding instead of subtracting the squared term (giving 16) or forgetting to square g(x) before combining (giving 14).",
  "apcalc-u1-007": "Factoring gives (x−3)(x+3)/(x−3), which simplifies to x+3 for x ≠ 3; substituting x = 3 into the simplified expression gives 6. The original 0/0 form does not mean the limit is 0 or nonexistent — it signals the need to simplify before substituting.",
  "apcalc-u1-008": "Multiplying numerator and denominator by the conjugate √(x+4)+2 gives [(x+4)−4]/[x(√(x+4)+2)] = x/[x(√(x+4)+2)] = 1/(√(x+4)+2), which approaches 1/4 as x→0; direct substitution before rationalizing gives the indeterminate form 0/0, which is not itself an answer of 0.",
  "apcalc-u1-009": "Since direct substitution yields the indeterminate form 0/0, the appropriate technique here is algebraic factoring (difference of cubes) followed by cancellation; conjugate multiplication is reserved for expressions containing radicals, and reporting 0/0 as a final answer misunderstands what an indeterminate form signifies.",
  "apcalc-u1-010": "The Squeeze Theorem states that if g(x) ≤ f(x) ≤ h(x) near a point and lim g = lim h = L, then lim f = L as well; here both −x² and x² → 0 as x→0, forcing x²sin(1/x) → 0 too, despite the oscillation of sin(1/x) itself, which is numerically damped out by the shrinking x² factor.",
  "apcalc-u1-011": "An open circle on a graph indicates the function is not defined at that input, while the table's trend toward 5 from both sides indicates the two-sided limit is 5; the limit value and the function's actual value at a point are conceptually distinct, so the limit can exist even when f(3) does not.",
  "apcalc-u1-012": "Since lim_{x→0} sin(x)/x = 1 (a standard limit confirmed numerically here), the two-sided limit exists and is finite, but it does not match the assigned value f(0) = 3; this mismatch between an existing finite limit and the function's actual value defines a removable discontinuity, not a jump or infinite one.",
  "apcalc-u1-013": "Continuity at x = 2 requires the left piece to equal the right piece's limit there: 3(2) + k = 2² = 4, so 6 + k = 4 and k = −2; a common error is setting k itself equal to the right-hand limit value of 4 rather than solving the resulting equation.",
  "apcalc-u1-014": "The formal definition of continuity at a point requires three simultaneous conditions: the function value exists, the two-sided limit exists, and the two agree; differentiability is a stronger condition not required for continuity, and the sign of one-sided limits is irrelevant to continuity.",
  "apcalc-u1-015": "Since 4 − x² ≥ 0 exactly when −2 ≤ x ≤ 2, the expression under the radical is defined and nonnegative throughout the closed interval, and the square root and polynomial functions are each continuous on their domains; f(−2) = f(2) = 0 are legitimate function values, not points of discontinuity.",
  "apcalc-u1-016": "Factoring gives (x−2)(x+1)/(x−2) = x+1 for x ≠ 2, so lim_{x→2} g(x) = 2+1 = 3; assigning g(2) = 3 removes the discontinuity by making the function value match the limit. Note that −1 is the zero of the simplified expression, not the limit's value at x = 2.",
  "apcalc-u1-017": "As x→3, the numerator approaches 4 (a positive constant) while the denominator (x−3)² approaches 0 through positive values from both sides, so the quotient grows without bound in the positive direction; this unbounded behavior corresponds exactly to a vertical asymptote at x = 3, and stating the limit is +∞ is a meaningful, standard way to describe it.",
  "apcalc-u1-018": "Dividing numerator and denominator by x² (the highest power present) gives (3 + 2/x)/(5 − 7/x²), and as x→∞ the terms with x in the denominator vanish, leaving 3/5; when numerator and denominator have equal degree, the limit at infinity equals the ratio of leading coefficients, not 0 or ∞.",
  "apcalc-u1-019": "The Intermediate Value Theorem guarantees at least one c in (0,3) with f(c)=0 because 0 lies between f(0) = −2 and f(3) = 5 and f is continuous on the interval; the theorem guarantees existence, not uniqueness, and it requires only continuity, not differentiability.",
  "apcalc-u1-020": "Because f(0) = 1 > 0 and f(1) ≈ −0.460 < 0, and f is continuous (a difference of continuous functions), the IVT guarantees at least one c in (0,1) with f(c) = 0; the theorem does not specify where this c is located (it need not be the midpoint) nor does it guarantee that c is unique.",
  "apcalc-u2-001": "Average velocity is the change in position divided by the change in time over the given interval: (22.4 - 9.8)/(4.5 - 1.5) = 12.6/3 = 4.2 m/s. Using the full interval [0, 4.5] instead of the specified [1.5, 4.5] gives the 4.47 distractor, which answers a different question.",
  "apcalc-u2-002": "The definition of the derivative at a point a is f'(a) = lim(h→0) [f(a+h) - f(a)]/h, so with a = 3 this becomes [f(3+h)-f(3)]/h. The third distractor is the symmetric difference quotient, which equals 2f'(3), not f'(3), and is used only for numerical estimation, not the formal definition.",
  "apcalc-u2-003": "The most accurate estimate from a symmetric table uses the centered difference quotient: [g(1.7) - g(1.5)]/(1.7-1.5) = 0.292/0.2 = 1.46. The 1.47 and 1.45 distractors come from one-sided (forward and backward) difference quotients, which are less accurate estimates of the instantaneous rate of change at 1.6, and 0.292 results from forgetting to divide by the change in x.",
  "apcalc-u2-004": "f is continuous everywhere, including at x=2, since |x-2|+1 is a sum of continuous functions. But the left-hand derivative at x=2 is -1 and the right-hand derivative is +1, so the two-sided limit defining f'(2) does not exist, giving a corner. Continuity never guarantees differentiability, so the first distractor states a false converse.",
  "apcalc-u2-005": "h(0) = 0 is defined and h is continuous there, but h'(x) = (2/3)x^(-1/3) approaches +infinity from the right and -infinity from the left as x -> 0, so the derivative does not exist (a vertical cusp). Having a minimum point does not by itself force the derivative to exist or equal zero, as this example shows.",
  "apcalc-u2-006": "Rewriting f(x) = 4x^5 - 3x^(-2) + x^(1/2) and applying the power rule term by term gives f'(x) = 20x^4 + 6x^(-3) + (1/2)x^(-1/2). The second distractor forgets to multiply by the original exponent 5 on the first term, and the third distractor fails to reduce the exponent of x^(1/2) by 1 when differentiating.",
  "apcalc-u2-007": "Since f is a constant function, f'(x) = 0, so h'(x) = 3g'(x) - 4f'(x) = 3(6x^2 - 5) - 0 = 18x^2 - 15. The first distractor mistakenly substitutes f(x) = 7 itself instead of f'(x) = 0. The third distractor forgets to multiply g'(x) by the constant factor 3.",
  "apcalc-u2-008": "Using d/dx[cos x] = -sin x, d/dx[e^x] = e^x, and d/dx[ln x] = 1/x term by term gives f'(x) = -5sin(x) - 3e^x + 2/x. The first distractor drops the negative sign from the derivative of cosine, and the second incorrectly differentiates e^x as if the power rule applied to it instead of using d/dx[e^x] = e^x.",
  "apcalc-u2-009": "By the product rule, f'(x) = (d/dx[x^3])·e^x + x^3·(d/dx[e^x]) = 3x^2 e^x + x^3 e^x. The first two distractors each keep only one of the two required terms, and the last distractor incorrectly applies the sum rule to a product.",
  "apcalc-u2-010": "By the product rule, r'(5) = p'(5)q(5) + p(5)q'(5) = (-1.2)(2.5) + (3.6)(4.1) = -3 + 14.76 = 11.76. Multiplying p'(5) and q'(5) together (giving -4.92) or subtracting the two products (giving -17.76) both misapply the product rule structure.",
  "apcalc-u2-011": "By the quotient rule, f'(x) = [(4x)(x+3) - (2x^2-1)(1)]/(x+3)^2 = [4x^2+12x-2x^2+1]/(x+3)^2 = (2x^2+12x+1)/(x+3)^2. The first distractor results from reversing the order of the two products in the numerator, and the second distractor forgets to square the denominator.",
  "apcalc-u2-012": "By the quotient rule, w'(-1) = [u'(-1)v(-1) - u(-1)v'(-1)]/[v(-1)]^2 = [(-2.1)(1.6) - (6.4)(3.3)]/(1.6)^2 = (-3.36 - 21.12)/2.56 = -9.5625. Reversing the order of the numerator terms flips the sign to give 9.5625, and forgetting to square v(-1) in the denominator gives -15.3.",
  "apcalc-u2-013": "Using d/dx[tan x] = sec^2 x and d/dx[sec x] = sec x tan x gives f'(x) = sec^2(x) - 3sec(x)tan(x). The first distractor swaps the two derivative formulas, and the second drops the required factor of sec(x) from the derivative of sec(x).",
  "apcalc-u2-014": "Using d/dx[cot x] = -csc^2 x and d/dx[csc x] = -csc x cot x gives g'(x) = -4csc^2(x) - csc(x)cot(x). The first distractor drops the negative sign from the derivative of csc(x), and the second drops the negative sign from the derivative of cot(x).",
  "apcalc-u3-001": "By the chain rule, the derivative of sin(u) is cos(u) times u prime, where u = 3x^2 - 1 and u prime = 6x, so h prime(x) = 6x cos(3x^2 - 1); omitting the factor of 6x or using the original inner function instead of its derivative are common chain rule errors.",
  "apcalc-u3-002": "The general power rule requires multiplying by the original exponent, reducing that exponent by one, and then multiplying by the derivative of the inner function 5x^3+2x, which is 15x^2+2; dropping any one of those three factors produces each distractor.",
  "apcalc-u3-003": "The chain rule states that d/dx of f(g(x)) equals f prime(g(x)) times g prime(x): the outer derivative must be evaluated at the inner function g(x), not at x itself, before multiplying by g prime(x); the distractors evaluate f prime at the wrong input or drop the inner-derivative factor.",
  "apcalc-u3-004": "Differentiating both sides requires the product rule on x^2 y and the chain rule on y^3, giving 2xy + x^2 y prime + 3y^2 y prime = 0; solving for y prime yields -2xy/(x^2+3y^2), while forgetting the y prime factor on y^3 or dropping the x^2 term leads to the distractors.",
  "apcalc-u3-005": "Applying the product rule to xy gives y + x y prime, and the chain rule to y^2 gives 2y y prime, so 2x + y + x y prime + 2y y prime = 0 leads to y prime = -(2x+y)/(x+2y); forgetting the +y term from the product rule or mishandling the chain rule on y^2 produces the distractors.",
  "apcalc-u3-006": "Differentiating gives cos(y) y prime + y + x y prime = 2x, since sin(y) needs the chain rule and xy needs the product rule; solving for y prime gives (2x-y)/(cos y + x), while a sign slip on the cos(y) term or dropping the product-rule term y changes the result.",
  "apcalc-u3-007": "Since g(f(x)) = x for inverse functions, differentiating with the chain rule gives g prime(f(x)) f prime(x) = 1, so g prime(4) = g prime(f(1)) = 1/f prime(1) = 1/5; using f prime(1) directly or the function value f(1) instead of its reciprocal derivative are common errors.",
  "apcalc-u3-008": "Since d/dx of arcsin(u) equals u prime over the square root of 1 minus u squared, with u = 2x and u prime = 2, f prime(x) = 2/sqrt(1-4x^2); evaluating at x = 0.2 gives 2/sqrt(0.84), approximately 2.182, while omitting the factor of 2 or squaring 2x incorrectly changes the value.",
  "apcalc-u3-009": "This requires the product rule on the two factors together with the chain rule inside each factor: y prime = 3e^(3x)sqrt(x^2+1) + xe^(3x)/sqrt(x^2+1); at x=2 this evaluates to about 3067.1, whereas multiplying the two factors' derivatives together or omitting a chain-rule factor gives smaller totals.",
  "apcalc-u3-010": "Differentiating x^2+y^2=25 implicitly twice gives y prime = -x/y and then y double-prime = -(x^2+y^2)/y^3, which simplifies to -25/y^3 using the original equation; at (3,4) this is -25/64, while using y instead of y^3 or omitting the y^2 term produces the distractors.",
  "apcalc-u4-001": "H'(t) is the derivative of temperature (in °F) with respect to time (in minutes), so its units are °F per minute. Because H'(6) is an instantaneous rate at the single moment t = 6, it does not describe a temperature value, a total change, or an average rate over an interval.",
  "apcalc-u4-002": "The table records velocity, not position or acceleration, so v(4) = -2 describes the particle's instantaneous motion at exactly t = 4: a negative velocity means the particle moves in the negative direction, and its speed is the absolute value of that velocity, 2 m/s.",
  "apcalc-u4-003": "The symmetric difference quotient (v(6) - v(2))/(6 - 2) = (-10 - 8)/4 = -4.5 approximates the acceleration at t = 4 by using the two table values that straddle t = 4, as the problem specifies; dividing by the wrong interval width or using only a one-sided difference produces the incorrect distractor values.",
  "apcalc-u4-004": "The velocity is v(t) = x'(t) = 3t^2 - 12t + 9 = 3(t - 1)(t - 3), an upward-opening parabola in t that is negative strictly between its two zeros, so the particle moves in the negative direction only when 1 < t < 3, not outside that interval or only at the zeros themselves.",
  "apcalc-u4-005": "The velocity is v(t) = x'(t) = 3t^2 - 18t + 24 = 3(t - 2)(t - 4), an upward-opening parabola in t whose values are negative strictly between its zeros, so the particle moves in the negative direction only for 2 < t < 4, not outside that interval or only at the zeros themselves.",
  "apcalc-u4-006": "dV/dt is the derivative of volume with respect to time, so it represents an instantaneous rate of change measured in cm³ per second, not a volume value itself, not a total accumulated change over an interval, and not the reciprocal (time per unit volume) rate.",
  "apcalc-u4-007": "Differentiating V = (4/3)πr^3 implicitly with respect to t requires the chain rule because r is itself a function of t: d/dt[(4/3)πr^3] = (4/3)π(3r^2)(dr/dt), and simplifying (4/3)(3) = 4 gives dV/dt = 4πr^2(dr/dt), with dr/dt appearing to the first power, not squared or omitted.",
  "apcalc-u4-008": "Let x and y be the distances from the wall to the bottom and top of the ladder. Since x^2 + y^2 = 169, when x = 5, y = 12. Differentiating gives 2x(dx/dt) + 2y(dy/dt) = 0, so dy/dt = -(x/y)(dx/dt) = -(5/12)(2) = -5/6, meaning the top slides down at 5/6 ft/sec.",
  "apcalc-u4-009": "Let x and y be the distances from the wall to the bottom and top of the ladder. Since x^2 + y^2 = 100, when x = 6, y = 8. Differentiating gives 2x(dx/dt) + 2y(dy/dt) = 0, so dy/dt = -(x/y)(dx/dt) = -(6/8)(2) = -3/2, meaning the top slides down at 3/2 ft/sec.",
  "apcalc-u4-010": "Since A = πr^2, differentiating with respect to time gives dA/dt = 2πr(dr/dt); substituting r = 50 and dr/dt = 3 gives dA/dt = 2π(50)(3) = 300π square meters per minute, roughly 942.5 m²/min.",
  "apcalc-u4-011": "Since f(25) = 5 and f'(x) = 1/(2√x) so f'(25) = 0.1, the linearization is L(x) = 5 + 0.1(x - 25); evaluating at x = 26.5 gives L(26.5) = 5 + 0.1(1.5) = 5.15, whereas omitting the factor of 1/2 or misreading the interval width produces the other listed values.",
  "apcalc-u4-012": "Direct substitution gives the indeterminate form 0/0, so L'Hopital's Rule applies: differentiating gives 2sin(2x)/(2x), which is again 0/0 at x = 0, so applying L'Hopital's Rule a second time gives 4cos(2x)/2, which evaluates to 4(1)/2 = 2 as x approaches 0.",
  "apcalc-u5-001": "The average rate of change is (25-1)/(5-1)=6. Since f'(x)=2x, setting 2c=6 gives c=3, which lies in (1,5) as MVT requires; c=6 is the average rate itself, not the point where it is attained.",
  "apcalc-u5-002": "Average rate = [f(2)-f(0)]/2 = 2. Solving 3c^2-2=2 gives c=±2√3/3≈±1.155; only the positive root lies in (0,2), so c≈1.155 is the value MVT guarantees.",
  "apcalc-u5-003": "EVT requires continuity on the entire closed interval. Since f has a vertical asymptote (an undefined value) at x=2, which lies inside [0,4], f fails to be continuous there, so EVT's hypothesis is not met and it gives no guarantee.",
  "apcalc-u5-004": "f'(x) = (2/3)(x-1)^(-1/3), which is never 0 but is undefined at x=1; since f itself is defined at x=1 (f(1)=0), x=1 qualifies as a critical number even though f' does not equal zero there.",
  "apcalc-u5-005": "f is increasing exactly where f'(x) > 0. The graph shows f'(x) > 0 on (2,4), while f'(x) < 0 on (-1,2) and (4,6), so f is actually decreasing on those intervals, not increasing throughout the whole domain.",
  "apcalc-u5-006": "By the First Derivative Test, f has a local maximum where f' changes from positive to negative, which occurs at x=-1. At x=2, f' changes from negative to positive (a local minimum), and at the endpoints x=-4 and x=6, f' does not change sign nearby, so neither is an interior extremum.",
  "apcalc-u5-007": "f'(x) = 6(x-2)(x+1), so f'(-2)=24>0 and f'(0)=-12<0, showing f' changes from positive to negative at x=-1, which by the First Derivative Test means f has a local maximum there; note f''(-1)=-18, not 0.",
  "apcalc-u5-008": "p'(x)=3x^2-8x=x(3x-8) gives critical points x=0 and x=8/3, both in [-1,3]. Evaluating all candidates: p(-1)=-3, p(0)=2, p(8/3)=-202/27≈-7.481, p(3)=-7. The smallest is -202/27 at x=8/3, not the endpoint x=3.",
  "apcalc-u5-009": "p'(x)=3x^2-6=0 gives x=±√2, but only x=-√2 lies in [-3,1]. Checking all candidates: p(-3)=-9, p(-√2)=4√2≈5.657, p(1)=-5. The largest value is 4√2 at x=-√2, not either endpoint.",
  "apcalc-u5-010": "The graph of f is concave down where f''(x) < 0. The table shows f''=-3 at x=-2 and f''=-1 at x=0, both negative, then f''=0 at x=2 and f'' becomes positive (2 and 4) afterward, so f is concave down exactly on (-2,2), not on all of (0,4) or the whole domain.",
  "apcalc-u5-011": "A correct Second Derivative Test justification must state both that x=-1 is a critical point (f'(-1)=0) and that f''(-1)<0, and must correctly conclude 'local maximum' from a negative second derivative; the distractors swap the roles of f' and f'', omit the critical-point condition, or flip the conclusion.",
  "apcalc-u5-012": "h'(x)=4x^3 and h''(x)=12x^2, so h''(0)=0, which makes the Second Derivative Test inconclusive; it does not by itself mean concave up, concave down, or 'no extremum.' Checking h' shows h'(-1)=-4<0 and h'(1)=4>0, a sign change from negative to positive, so x=0 is in fact a local minimum by the First Derivative Test.",
  "apcalc-u5-013": "f'(x)>0 everywhere means f is increasing on its entire domain, with no critical points, so a local maximum is impossible; f''(x)<0 everywhere means the graph is concave down, so the increasing rate slows rather than accelerates as x grows.",
  "apcalc-u5-014": "f''(x) is negative at x=-2 and x=0, then zero at x=2, then positive at x=4 and x=6, so concavity switches from down to up at x=2, giving a genuine inflection point. Although f'(2)=0, f' stays nonnegative on both sides (1 before, 1 after), so it never changes sign and x=2 is not a local extremum; concavity does not determine whether f is increasing or decreasing, which depends on f', not f''.",
  "apcalc-u5-015": "Differentiating implicitly: 2x+2yy'-4-6y'=0, so y'=(2-x)/(y-3). A horizontal tangent requires the numerator to equal zero (with a nonzero denominator): x=2, occurring at the points (2,0) and (2,6). Setting the denominator y-3=0 instead gives x=-1 and x=5, which are where the tangent line is vertical, not horizontal.",
  "apcalc-u5-016": "The fencing constraint is x + 2y = 120 (one side of length x plus two sides of length y), so y=60-x/2. Area = xy = x(60-x/2) = 60x - x²/2. The distractor 120x-x² wrongly assumes fencing is needed on all four sides, and x(60-x) drops the factor of 1/2 when solving for y.",
  "apcalc-u5-017": "With h=500/(πr²), surface area is S(r)=2πr²+1000/r. Solving S'(r)=4πr-1000/r²=0 gives r³=250/π, so r=(250/π)^(1/3)≈4.30 cm; since S''(r)=4π+2000/r³>0 for all r>0, this critical point is a minimum. The distractor 79.58 is the value of r³ before taking the cube root, a common final-step omission.",
  "apcalc-u5-018": "With h=50000/x², surface area is S(x)=x²+4x·(50000/x²)=x²+200000/x. Solving S'(x)=2x-200000/x²=0 gives x³=100000, so x=(100000)^(1/3)≈46.42 cm; since S''(x)=2+400000/x³>0 for all x>0, this is a minimum. The distractor 100,000 is the unsimplified value of x³, with the cube root never taken.",
  "apcalc-u6-001": "Total accumulated change equals the integral of the rate over the interval, so gallons pumped out equal ∫r(t)dt from 0 to 10; r(10)-r(0) instead gives the change in the rate itself rather than the accumulated amount, integrating r'(t) recovers only r(10)-r(0) again by the Net Change Theorem, and dividing by 10 computes an average rate, not a total quantity.",
  "apcalc-u6-002": "A left Riemann sum uses the velocity at the left endpoint of each subinterval, giving 3(v(0)+v(3)+v(6)+v(9)) = 3(2+5+9+7) = 69 meters; using the right endpoints instead gives 75 (a right sum), averaging the left and right sums gives 72 (the trapezoidal estimate), and multiplying by all five table values instead of just the first four gives 81, which double counts a subinterval.",
  "apcalc-u6-003": "A right Riemann sum uses the rate at the right endpoint of each 2-hour subinterval: 2(L(2)+L(4)+L(6)+L(8)) = 2(42+35+25+15) = 234 liters; using the left endpoints instead gives 304, averaging the two sums gives the trapezoidal estimate of 269, and summing the four rate values without multiplying by the 2-hour subinterval width gives 117, which has the wrong units for an accumulated quantity.",
  "apcalc-u6-004": "The trapezoidal sum averages the left and right endpoint rates on each subinterval: 0.5[(0.2+0.5)+(0.5+0.9)+(0.9+0.6)+(0.6+0.3)] = 0.5(4.5) = 2.25 inches; using only left endpoints gives 2.2, using only right endpoints gives 2.3, and forgetting the factor of one-half in the trapezoidal formula doubles the estimate to 4.5.",
  "apcalc-u6-005": "A right Riemann sum with n = 4 equal subintervals of width Δt = 3 seconds multiplies Δt by the velocity at the right endpoint of each subinterval, giving 3[v(3)+v(6)+v(9)+v(12)] = 75 meters; using the left endpoints t = 0,3,6,9 describes a left sum instead, omitting the factor of 3 gives an expression with the wrong units, and including all five table values uses one more term than the four subintervals require.",
  "apcalc-u6-006": "By definition, a definite integral is the limit as n approaches infinity of the Riemann sum Σf(x_i)Δx; omitting the limit leaves only a finite approximating sum rather than the exact integral, dividing by n instead of multiplying by Δx = 5/n changes the scale of every term by an incorrect factor, and squaring Δx introduces an extra factor that no longer corresponds to the area interpretation of the integral.",
  "apcalc-u6-007": "By the Fundamental Theorem of Calculus combined with the chain rule, since the upper limit is x^2 rather than x, g'(x) equals the integrand evaluated at x^2 times the derivative of x^2, giving √((x^2)^2+1)·2x = 2x√(x^4+1); dropping the factor 2x ignores the chain rule needed for the composite upper limit, and evaluating the integrand at t = x instead of t = x^2 fails to substitute the actual upper limit.",
  "apcalc-u6-008": "By the Fundamental Theorem of Calculus, g'(x) = f(x), so the given sign change of f from positive to negative at x = 4 means g' changes from positive to negative there, and the First Derivative Test confirms a local maximum; f(4) = 0 only tells us g'(4) = 0, which alone is not conclusive, a sign change described backward would actually justify a local minimum, and f decreasing near x = 4 implies g is concave down only near x = 4, not for all x.",
  "apcalc-u6-009": "Since D'(t) = v(t) > 0 at every recorded value, D is increasing throughout the table, but D increases at a decreasing rate exactly where v itself is decreasing; the table shows v rising from 2 to 9 on [0,6], meaning D increases at an increasing rate there, and v falling from 9 to 4 on [6,12], so D increases at a decreasing rate only on 6 < t < 12.",
  "apcalc-u6-010": "By additivity of integrals, ∫_{1}^{3} f(x) dx = ∫_{1}^{5} f(x) dx - ∫_{3}^{5} f(x) dx = 8 - 5 = 3, so ∫_{1}^{3}[2f(x)-g(x)]dx = 2(3) - 4 = 2 by linearity; adding the two given f-integrals instead of subtracting gives 13 for the piece and leads to 22, adding g instead of subtracting it gives 10, and forgetting to distribute the factor of 2 onto the f-integral before subtracting g gives -1.",
  "apcalc-u6-011": "An antiderivative is F(x) = 2x^(3/2) + 2/x, since ∫3√x dx = 2x^(3/2) and ∫-2x^(-2) dx = 2x^(-1); so F(4)-F(1) = (16+0.5)-(2+2) = 25/2. Evaluating F(1)-F(4) instead reverses the order and gives -25/2, using -2/x as the antiderivative of -2x^(-2) (a sign error) gives 31/2, and dropping the leading coefficient 3 before integrating √x gives 19/6.",
  "apcalc-u6-012": "The integrand √(1+x^3) has no elementary antiderivative, so the definite integral must be approximated numerically using a calculator's integration feature, which gives ∫_{0}^{1}√(1+x^3)dx ≈ 1.111; since 1+x^3 > 1 on (0,1], the value must exceed the length of the interval (1), ruling out 1.000 or a value below it, while 1.500 substantially overestimates and 0.833 underestimates the true value.",
  "apcalc-u6-013": "The general antiderivative is F(x) = 2x^3 - 2x^2 + x + C; substituting f(1) = 5 gives 2 - 2 + 1 + C = 5, so C = 4 and f(x) = 2x^3 - 2x^2 + x + 4. Leaving C = 0 ignores the given initial condition entirely, integrating -4x as -4x^2 instead of -2x^2 misapplies the power rule by forgetting to divide by the new exponent, and integrating -4x as +2x^2 flips the sign of that term.",
  "apcalc-u6-014": "The general antiderivative is F(x) = x^4 + 3x^2 - 2x + C; substituting f(0) = -1 gives 0 + 0 - 0 + C = -1, so C = -1 and f(x) = x^4 + 3x^2 - 2x - 1. Leaving C = 0 ignores the initial condition, integrating 6x as 6x^2 instead of 3x^2 forgets to divide by the new exponent, and integrating -2 as +2x flips the sign of the constant term's antiderivative.",
  "apcalc-u6-015": "Let u = x^2, so du = 2x dx and x dx = du/2; then ∫cos(u)(du/2) = (1/2)sin(u) + C = (1/2)sin(x^2) + C. Forgetting the factor of 1/2 that comes from solving for x dx in terms of du gives sin(x^2)+C, a sign slip gives the negative of the correct answer, and forgetting to substitute u back as x^2 leaves an expression that no longer matches the original variable.",
  "apcalc-u6-016": "Let u = x^4+5, so du = 4x^3 dx and x^3 dx = du/4; then ∫√u (du/4) = (1/4)·(2/3)u^(3/2)+C = (1/6)(x^4+5)^(3/2)+C. Omitting the 2/3 factor from the power rule leaves (1/4)(x^4+5)^(3/2), omitting the 1/4 factor that comes from the substitution leaves (2/3)(x^4+5)^(3/2), and failing to raise the exponent from 1/2 to 3/2 during the power rule leaves the wrong power entirely.",
  "apcalc-u6-017": "Long division gives (2x^2-x-1)/(x+1) = (2x-3) + 2/(x+1), so integrating term by term gives x^2 - 3x + 2ln|x+1| + C. Omitting the remainder 2/(x+1) drops the logarithmic term entirely, forgetting the coefficient 2 on that term understates it, and a subtraction sign error during the long division (yielding quotient 2x+3 instead of 2x-3) flips the sign of the linear term to x^2 + 3x.",
  "apcalc-u6-018": "Since e^(-x^2) has no elementary antiderivative expressible with standard AB techniques, the definite integral must be approximated numerically, and a calculator's numerical integration gives ∫_{0}^{2}e^(-x^2)dx ≈ 0.882. Attempting u-substitution fails because there is no extra factor of x outside the exponential to absorb into du, treating e^(-x^2) with the power rule confuses an exponential function with a power function, and completing the square does not simplify -x^2, so no elementary antiderivative results regardless of the algebraic manipulation.",
  "apcalc-u7-001": "Since the volume is decreasing over time, dV/dt must be negative, and 'proportional to the square root of V' means the rate depends on √V itself (not V² or 1/√V), so dV/dt = -k√V with k > 0 is the only choice matching both the sign and the stated proportionality.",
  "apcalc-u7-002": "Differentiating y = 5e^(x²) using the chain rule gives dy/dx = 5(2x)e^(x²) = 2x·5e^(x²) = 2xy, so substitution confirms it satisfies the equation identically, while the other three functions produce derivatives that do not equal 2xy when substituted back in.",
  "apcalc-u7-003": "The field shows slope 0 along both entire axes and matching-sign slopes in the first/third quadrants (positive) versus second/fourth quadrants (negative), exactly the sign pattern of xy/2; -xy/2 would reverse every one of those signs, x/y is undefined along the x-axis instead of equal to 0 there, and x+y is not 0 along the whole y-axis.",
  "apcalc-u7-004": "For x > 0 and y > 0 the slope xy/2 is positive and grows larger as both x and y grow, so the curve rises ever more steeply; differentiating the slope shows d²y/dx² = (y/2)(1 + x²/2) > 0 in this region, confirming the curve is increasing and concave up rather than leveling off or decreasing.",
  "apcalc-u7-005": "Separating variables gives y dy = x² dx; integrating both sides yields y²/2 = x³/3 + C₁, and multiplying every term by 2 (then renaming the constant) gives the implicit general solution y² = (2/3)x³ + C, not the equation with the un-doubled coefficient 1/3 or a stray x attached to C.",
  "apcalc-u7-006": "Separating variables gives y² dy = x dx; integrating both sides yields y³/3 = x²/2 + C₁, and multiplying every term by 3 (then renaming the constant) gives the implicit general solution y³ = (3/2)x² + C, not a version with the fraction inverted or an extra factor of x on the constant.",
  "apcalc-u7-007": "Separating variables gives dy/y = 3x² dx, so ln|y| = x³ + C₁ and y = Ae^(x³); applying y(0) = 2 gives A = 2, so the particular solution is y = 2e^(x³), whereas dividing the exponent by 3 or replacing x³ with 3x comes from mis-integrating 3x² dx.",
  "apcalc-u7-008": "Evaluating y(1.2) = 5e^(1.2⁴) = 5e^(2.0736) ≈ 5(7.951) ≈ 39.8, which rounds to 40; using 1.2³ instead of 1.2⁴ in the exponent gives about 28, omitting the leading factor of 5 gives about 8, and adding 5 instead of multiplying by it gives about 13.",
  "apcalc-u7-009": "Solving P = 10000e^(kt) with P(5) = 13000 gives k = ln(1.3)/5 ≈ 0.0525; setting 10000e^(kt) = 20000 gives t = ln2/k ≈ 13.21 years after 2020, so the population passes 20,000 partway through 2033; using a linear growth rate, an incorrectly averaged k, or forgetting to divide by the 5-year span each yield a different wrong year.",
  "apcalc-u7-010": "Since A = A₀e^(-kt) and A(12) = 0.25A₀, solving 0.25 = e^(-12k) gives k = -ln(0.25)/12 = ln(4)/12 ≈ 0.116; doubling the elapsed time to 24 years, using ln(4)/6, or forgetting to divide ln(4) by 12 at all produce the other three listed values instead.",
  "apcalc-u8-001": "The average value of A on [0,8] is (1/8)∫₀⁸A(x)dx. Approximating the integral with the trapezoidal rule using the five table values gives (2/2)[10+2(14)+2(20)+2(22)+18] = 140, so the average area is 140/8 = 17.5 cm². Using only left endpoints or only right endpoints instead of trapezoids, or simply averaging the five listed A-values without weighting the interior points twice, produces the other listed answers.",
  "apcalc-u8-002": "Position is found from x(4) = x(0) + ∫₀⁴v(t)dt. Since ∫₀⁴(3t²−12t+9)dt = [t³−6t²+9t]₀⁴ = 4, x(4) = 2 + 4 = 6. The answer 4 omits the initial position, −2 comes from a sign error (2−4), and 14 mistakenly adds the total distance traveled (12, found by splitting at v's zeros t=1,3) instead of the net displacement (4).",
  "apcalc-u8-003": "Total distance requires ∫₀³|v(t)|dt, not the plain signed integral. Since v(t)=0 at t≈0.412 and t≈2.730, velocity is negative, then positive, then negative on the three resulting subintervals; summing the absolute value of each piece gives about 5.106 ft. Using the signed integral directly gives only the net displacement (3.950 ft), splitting at just the first sign change and missing the third piece gives 4.761 ft, and evaluating sin(t) with the calculator in degree mode instead of radian mode gives 5.607 ft.",
  "apcalc-u8-004": "The amount in the tank equals the initial amount plus the accumulated inflow: 50+∫₀¹⁰R(t)dt = 50+[20t−10cos(t/2)]₀¹⁰ = 50+(210−10cos5) ≈ 257.163 gallons. Omitting the initial 50 gallons gives 207.163, approximating the inflow as the constant endpoint rate R(10) times 10 minutes (plus 50) gives 202.054, and evaluating the sine in degree mode instead of radian mode gives 252.180.",
  "apcalc-u8-005": "Since f(x) ≥ g(x) on [−1,2], the area is ∫₋₁²[(x+2)−x²]dx = [x²/2+2x−x³/3]₋₁² = 9/2. Forgetting to subtract g(x) and integrating f(x) alone over the same interval gives 15/2, integrating only over [0,2] instead of the full region gives 10/3, and shifting the bounds to [−2,1] gives 3/2.",
  "apcalc-u8-006": "The curves intersect where 8−x² = x², i.e., x = ±2, and f(x) ≥ g(x) throughout [−2,2]. The area is ∫₋₂²[(8−x²)−x²]dx = ∫₋₂²(8−2x²)dx = 64/3. Forgetting to subtract g(x) and integrating only f(x) gives 80/3, integrating over just half the interval (0 to 2) gives 32/3, and doubling the correct area by mistake gives 128/3.",
  "apcalc-u8-007": "Solving 6−y² = y gives y = −3 and y = 2, and the curve x=6−y² lies to the right of x=y on [−3,2]. The area is ∫₋₃²[(6−y²)−y]dy = 125/6. Using the wrong sub-interval [0,2] instead of the full [−3,2] gives 22/3, forgetting to subtract the boundary x=y and integrating only 6−y² gives 55/3, and extending the bounds to [−3,3] instead of stopping at the true intersection y=2 gives 18.",
  "apcalc-u8-008": "Because f is positive on (−2,0) and negative on (0,2), the enclosed area must be computed piecewise: ∫₋₂⁰f(x)dx − ∫₀²f(x)dx = 4+4 = 8. Simply evaluating the single definite integral ∫₋₂²f(x)dx gives 0, since the positive and negative pieces cancel by odd-function symmetry — that is a signed net change, not an enclosed area. Computing only one of the two pieces gives 4, and doubling the correct total by mistake gives 16.",
  "apcalc-u8-009": "A right Riemann sum uses the area value at the right endpoint of each subinterval: V ≈ Δx[A(2)+A(4)+A(6)+A(8)] = 2(14+20+22+18) = 148 cm³. Using left endpoints instead gives 132 cm³, using the trapezoidal rule instead of a right sum gives 140 cm³, and summing the areas without multiplying by the subinterval width Δx=2 gives only 74 cm³.",
  "apcalc-u8-010": "At each x, the diameter is √x, so the radius is √x/2 and each semicircular cross section has area (1/2)π(√x/2)² = πx/8. The volume is ∫₀⁴(πx/8)dx = π. Treating the cross sections as full circles instead of semicircles gives 2π, mistakenly using √x itself as the radius rather than half the diameter gives 4π, and using square cross sections of side √x instead of semicircles gives 8.",
  "apcalc-u8-011": "By the disc method, V = π∫₀²(x²)²dx = π∫₀²x⁴dx = π[x⁵/5]₀² = 32π/5. Forgetting to square the radius before integrating gives π∫₀²x²dx = 8π/3, mistakenly integrating x³ instead of x⁴ gives 4π, and dividing the correct result by an extra factor of 2 gives 16π/5.",
  "apcalc-u8-012": "By the disc method about the y-axis, V = π∫₀³(y²)²dy = π∫₀³y⁴dy = π[y⁵/5]₀³ = 243π/5. Forgetting to square the radius gives π∫₀³y²dy = 9π, mistakenly reusing the bounds and setup from a different revolution about the x-axis on [0,2] gives 32π/5, and forgetting to include the factor of π entirely gives 243/5.",
  "apcalc-u8-013": "Since the axis y=1 coincides with the lower boundary of R, the radius at each x is (e^(x/2)+1)−1 = e^(x/2), so V=π∫₀²(e^(x/2))²dx=π∫₀²eˣdx=π(e²−1)≈20.072. Forgetting to square the radius before integrating gives 2π(e−1), forgetting to shift the radius down by 1 and using the full function value as the radius gives π(e²+4e−3), and mistakenly using the upper bound x=1 instead of x=2 gives π(e−1).",
  "apcalc-u8-014": "Since both f and g are nonnegative on [−1,2], the outer radius is f(x)=x+2 and the inner radius is g(x)=x², so V=π∫₋₁²[(x+2)²−(x²)²]dx=72π/5. Using only the outer curve and ignoring the inner radius entirely (disc instead of washer) gives 21π, squaring only the outer function while leaving the inner term unsquared gives 18π, and forgetting to square either radius and using f−g directly gives 9π/2.",
  "apcalc-u8-015": "The curves intersect where 8−x²=x+3, giving x=(−1±√21)/2, and both f and g stay positive throughout this interval with f≥g. So V=π∫[(8−x²)²−(x+3)²]dx evaluated over these bounds ≈463.570. Using only the outer radius and ignoring the inner boundary (disc method instead of washer) gives 578.743, computing π∫(f−g)dx without squaring the radii gives 50.388, and omitting the factor of π entirely gives 147.559.",
  "apcalc-u8-016": "Revolving about y=6, the farther boundary y=x² generates the outer radius 6−x² and the closer boundary y=4 generates the constant inner radius 6−4=2, so the correct washer integral is π∫₋₂²[(6−x²)²−2²]dx, which evaluates to 384π/5. Omitting the inner radius entirely turns the washer into an incorrect disc setup, squaring the difference of the two radii instead of taking the difference of their squares is a common algebra error since (A−B)²≠A²−B², and applying a shell-type 2πrh formula while integrating with respect to x is the wrong method for a horizontal axis of revolution here.",
  "apcalc-u8-017": "Since y' = √x, the arc length is ∫₀³√(1+x)dx = [(2/3)(1+x)^(3/2)]₀³ = (2/3)(8−1) = 14/3. Forgetting to add 1 under the square root and using |y'|=√x directly gives 2√3, computing the area under the curve instead of the arc length gives 12√3/5, and dropping the 2/3 coefficient when evaluating the antiderivative gives 7.",
  "apcalc-u8-018": "The arc length is ∫₀^(π/2)√(1+cos²x)dx ≈ 1.910, which must be evaluated numerically since it has no elementary closed form. Dropping the 1 inside the square root reduces the integrand to |cos x|, giving ∫₀^(π/2)|cos x|dx=1, using only the horizontal interval width π/2≈1.571 ignores the curve's rise entirely, and computing the straight-line chord distance between the endpoints (0,0) and (π/2,1) instead of the arc length gives about 1.862.",
};

