for (const [groupId, ids] of Object.entries(CALC_VARIANT_GROUPS)) {
  ids.forEach((id) => {
    const question = CALC_QUESTIONS.find((candidate) => candidate.id === id);
    if (!question) throw new Error(`Missing Calculus AB variant ${id}`);
    question.variantGroupId = groupId;
  });
}

CALC_QUESTIONS.forEach((question) => {
  const explanation = CALC_EXPLANATIONS[question.id];
  if (!explanation) throw new Error(`Missing Calculus AB explanation for ${question.id}`);
  question.e = explanation;
});

window.QUESTIONS_AP_CALCULUS_AB = CALC_QUESTIONS;
